namespace { \
    ogn::NodeTypeBootstrapImpl<LidarBasicVizTranscoder, LidarBasicVizTranscoderDatabase> s_registration("omni.sensors.nv.lidar.LidarBasicVizTranscoder", 1, "omni.sensors.nv.lidar"); \
}
